        "Each slot holds a complete snapshot of all 20 zone masks.",
        "Multiple slots let you keep several layouts at once without repainting.",
        "Slots survive image switches. Copy, switch images, paste.",
        "The slot label shows what was last saved there.",
        "Swap between slots to compare different zone arrangements.",
        "Select a slot then hit Copy All or Paste All.",
        "It's a dropdown. Pick a slot. Use Copy All or Paste All on it.",
